/**
 * @suppress
 */
public object FfiConverterTypeEngineView: FfiConverter<EngineView, Long> {
    override fun lower(value: EngineView): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): EngineView {
        return EngineView(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): EngineView {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: EngineView) = 8UL

    override fun write(value: EngineView, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



